const D = { energy: .6, scale: 1, speed: 1, density: .5, hetero: .6, bands: .5, hue: 190, x: .5, y: .5, style: 'isochrone', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Eikonal equation |grad T| = 1/v(x) solved by fast sweeping (Godunov upwind).
// T is the FIRST-ARRIVAL travel time from a set of drifting seeds through a heterogeneous
// medium: wavefronts refract around slow regions, fold into cusps and collide into shock
// seams. With a uniform v this degenerates to a Voronoi diagram — the heterogeneity is the
// whole point, it makes every boundary CURVE. ----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW * height / width));
const N = BW * BH;
const BIG = 1e9;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.T = new Float32Array(N); S.V = new Float32Array(N); S.ID = new Int16Array(N);
}

const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}
function vn3(x, y, z) {
  const ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
  const fx = x - ix, fy = y - iy, fz = z - iz;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy), w = fz * fz * (3 - 2 * fz);
  const a0 = hsh(ix, iy, iz), a1 = hsh(ix + 1, iy, iz), a2 = hsh(ix, iy + 1, iz), a3 = hsh(ix + 1, iy + 1, iz);
  const b0 = hsh(ix, iy, iz + 1), b1 = hsh(ix + 1, iy, iz + 1), b2 = hsh(ix, iy + 1, iz + 1), b3 = hsh(ix + 1, iy + 1, iz + 1);
  const x00 = a0 + (a1 - a0) * u, x10 = a2 + (a3 - a2) * u, x01 = b0 + (b1 - b0) * u, x11 = b2 + (b3 - b2) * u;
  const y0 = x00 + (x10 - x00) * v, y1 = x01 + (x11 - x01) * v;
  return y0 + (y1 - y0) * w;
}
function fbm3(x, y, z) { return 0.58 * vn3(x, y, z) + 0.27 * vn3(x * 2.09 + 5.1, y * 2.09 - 3.2, z * 1.6 + 1.3) + 0.15 * vn3(x * 4.17 - 2.3, y * 4.17 + 7.7, z * 2.7 - 4.1); }

const tt = K.t;
const sp = 0.3 + P.speed * 0.9;

// ---- the medium: a slow/fast velocity field that drifts and evolves in place ----
const het = P.hetero;
const zf = tt * 0.031 * sp + 5.1;
const mx = 0.9 * Math.sin(tt * 0.037) + 0.4 * Math.sin(tt * 0.089 + 1.4);
const my = 0.7 * Math.cos(tt * 0.051) + 0.3 * Math.sin(tt * 0.113 + 0.5);
const fsv = 3.1 / BH;
const V = S.V;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  const f = fbm3(i * fsv + mx, j * fsv + my, zf);
  // v in [1-0.82*het, 1+0.35*het]: slow lenses bend the fronts hard, fast channels race ahead
  V[j * BW + i] = Math.max(0.14, 1 + (f - 0.5) * 2 * (het * 0.6) - het * 0.24);
}

// ---- seeds: drift on incommensurate rates so the whole front structure reorganises forever ----
const nS = Math.max(2, Math.min(9, 2 + Math.round(P.density * 7)));
const T = S.T, ID = S.ID;
T.fill(BIG); ID.fill(-1);
for (let s = 0; s < nS; s++) {
  const a1 = 0.29 + hsh(s * 5 + 1, 2, 4) * 0.72, a2 = 0.23 + hsh(s * 5 + 2, 3, 4) * 0.66;
  const b1 = hsh(s * 5 + 3, 4, 4) * 6.28, b2 = hsh(s * 5 + 4, 5, 4) * 6.28;
  const sx = (0.5 + 0.40 * Math.sin(tt * a1 * 0.19 + b1) + 0.09 * Math.sin(tt * 0.41 + s)) * (BW - 1);
  const sy = (0.5 + 0.38 * Math.cos(tt * a2 * 0.17 + b2) + 0.08 * Math.sin(tt * 0.33 + s * 1.7)) * (BH - 1);
  const p = (sy | 0) * BW + (sx | 0);
  T[p] = 0; ID[p] = s;
}

// ---- fast sweeping: 4 alternating-direction Gauss-Seidel sweeps with the Godunov upwind
// update. T is rebuilt from BIG every frame (the medium drifts, so relaxing the previous
// solution would let it creep monotonically downhill to a wrong answer). ----
function solve(i, j) {
  const p = j * BW + i;
  const f = 1 / V[p];                        // slowness
  const a = Math.min(i > 0 ? T[p - 1] : BIG, i < BW - 1 ? T[p + 1] : BIG);
  const b = Math.min(j > 0 ? T[p - BW] : BIG, j < BH - 1 ? T[p + BW] : BIG);
  let tn;
  if (Math.abs(a - b) >= f) tn = Math.min(a, b) + f;            // one-sided update
  else tn = 0.5 * (a + b + Math.sqrt(2 * f * f - (a - b) * (a - b)));
  if (tn < T[p]) {
    T[p] = tn;
    // inherit the source of whichever neighbour actually fed us
    const ia = (i > 0 ? T[p - 1] : BIG) <= (i < BW - 1 ? T[p + 1] : BIG) ? (i > 0 ? p - 1 : -1) : (i < BW - 1 ? p + 1 : -1);
    const ib = (j > 0 ? T[p - BW] : BIG) <= (j < BH - 1 ? T[p + BW] : BIG) ? (j > 0 ? p - BW : -1) : (j < BH - 1 ? p + BW : -1);
    const ta = ia >= 0 ? T[ia] : BIG, tb = ib >= 0 ? T[ib] : BIG;
    const src = ta <= tb ? ia : ib;
    if (src >= 0 && ID[src] >= 0) ID[p] = ID[src];
  }
}
for (let pass = 0; pass < 2; pass++) {
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) solve(i, j);
  for (let j = 0; j < BH; j++) for (let i = BW - 1; i >= 0; i--) solve(i, j);
  for (let j = BH - 1; j >= 0; j--) for (let i = BW - 1; i >= 0; i--) solve(i, j);
  for (let j = BH - 1; j >= 0; j--) for (let i = 0; i < BW; i++) solve(i, j);
}

// ---- render ----
let tmax = 1e-6;
for (let i = 0; i < N; i++) if (T[i] < BIG && T[i] > tmax) tmax = T[i];
const itm = 1 / tmax;
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 15 + Math.sin(tt * 0.0193) * 20) % 360 + 360) % 360;
const gain = 0.5 + P.energy * 1.2 + A.rms * 0.4;
const nb = 3 + P.bands * 22;                      // isochrone count
// the bands march OUTWARD from the sources at an incommensurate rate (a lone constant rate
// would re-phase; T itself also drifts, so the frame never repeats)
const bph = tt * (0.10 + P.speed * 0.14) + 0.03 * Math.sin(tt * 0.27);
function pal(m, sp2, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + sp2)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + sp2 * 2))];
}
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    const p = jc + i;
    const tn = (T[p] >= BIG ? tmax : T[p]) * itm;
    const id = ID[p] < 0 ? 0 : ID[p];
    // shock seams: where neighbouring cells arrived from different sources
    const seam = (ID[jc + im] !== id || ID[jc + ip] !== id || ID[jm + i] !== id || ID[jp + i] !== id) ? 1 : 0;
    // |grad T| deviation from the local slowness marks caustics where the front folds
    const gx = (T[jc + ip] >= BIG ? tmax : T[jc + ip]) - (T[jc + im] >= BIG ? tmax : T[jc + im]);
    const gy = (T[jp + i] >= BIG ? tmax : T[jp + i]) - (T[jm + i] >= BIG ? tmax : T[jm + i]);
    const gmag = Math.sqrt(gx * gx + gy * gy) * 0.5;
    const fold = Math.max(0, 1 - gmag * V[p] * 2.6);   // near 1 where the front is folded/stalled
    const ph = tn * nb - bph * nb;
    const band = 0.5 + 0.5 * Math.cos(6.2831 * ph);
    const sharp = Math.pow(band, 2.2);
    const vel = V[p];
    let r, gg, b;
    if (style === 'caustic') {                 // fold ridges blaze; the medium sits dark
      const c = pal(0.08 + tn * 0.5, 0.19, 0.0);
      const base = 0.10 + vel * 0.10;
      const hot = (fold * 0.85 + sharp * 0.35 + seam * 0.5) * gain;
      r = Math.min(1, c[0] * base + hot * 0.95); gg = Math.min(1, c[1] * base + hot * 0.92); b = Math.min(1, c[2] * base + hot * 1.0);
    } else if (style === 'bathymetry') {       // muted depth chart: tonal isochrone terraces
      // the tonal ramp must key off tn (bounded 0..1) — keying it off the marching band
      // index lets it run negative and blow the whole chart white
      const terr = Math.floor(ph);
      const alt = ((terr % 2) + 2) % 2;
      const c = pal(0.52 + tn * 0.30, 0.12, 0.0);
      const sh = (0.18 + (1 - tn) * 0.52) * (0.6 + gain * 0.4) * (0.86 + alt * 0.14);
      r = Math.min(1, c[0] * sh * 0.8 + seam * 0.10); gg = Math.min(1, c[1] * sh * 0.92 + seam * 0.12); b = Math.min(1, c[2] * sh * 1.05 + seam * 0.16);
    } else if (style === 'interferogram') {    // dense fringes only — radically abstracted
      const fr = 0.5 + 0.5 * Math.cos(6.2831 * (tn * (nb * 2.4) - bph * nb * 1.6));
      const v = 0.16 + fr * 0.72 * (0.5 + gain * 0.4);
      r = Math.min(1, v * 0.92); gg = Math.min(1, v * 1.0); b = Math.min(1, v * 0.86);
    } else if (style === 'thermal') {
      const m = Math.min(1, ((1 - tn) * 0.72 + sharp * 0.18) * (0.5 + P.energy * 0.85));
      r = Math.min(1, m * 2.15); gg = Math.min(1, Math.max(0, m * 2.0 - 0.55)); b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.4 - m * 1.5));
    } else {                                   // isochrone (default) — travel-time tomography
      // each source owns a hue; arrival bands ripple outward through its domain
      const c = pal(id * 0.146 + 0.03, 0.2, 0.0);
      const sh = (0.30 + (1 - tn) * 0.42) * (0.6 + gain * 0.42);   // brighter near the source
      const rip = band * (0.16 + 0.24 * P.bands) * gain;
      const dark = 1 - seam * 0.55;                                 // shock seams etch dark
      r = Math.min(1, (c[0] * sh + rip * 0.55 + fold * 0.18) * dark);
      gg = Math.min(1, (c[1] * sh + rip * 0.6 + fold * 0.2) * dark);
      b = Math.min(1, (c[2] * sh + rip * 0.68 + fold * 0.24) * dark);
    }
    const o = 4 * p;
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
